        L("desk.folders.setup_not_written", table: "DeskFolders", item)
    }

    /// Preparing the download…
    ///
    /// otc-sync: Set Up a New Device's progress dialog before the image's download starts (its signed checksum is fetched first).
    static var deskFoldersSetupPreparingDownload: String { L("desk.folders.setup_preparing_download", table: "DeskFolders") }

    /// Start
    ///
    /// otc-sync: button of Set Up a New Device's first dialog that starts the download.
    static var deskFoldersSetupStart: String { L("desk.folders.setup_start", table: "DeskFolders") }

    /// The setup stopped:
    ///
    /// {detail}
    ///
    /// otc-sync: error dialog of Set Up a New Device. {detail} is the reason on its own paragraph (for example "the card is too small (4.0 GB) - it needs 8 GB or more").
    static func deskFoldersSetupStopped(detail: String) -> String {
        L("desk.folders.setup_stopped", table: "DeskFolders", detail)
    }

    /// Set Up a New Device
    ///
    /// Both apps: title of the window (Mac) or of every dialog (otc-sync) of the wizard that downloads the device image and puts it on an SD card for a new Raspberry Pi device. Title Case, as a window title.
    static var deskFoldersSetupTitle: String { L("desk.folders.setup_title", table: "DeskFolders") }

    /// Waiting for permission…
    ///
    /// otc-sync: Set Up a New Device's progress dialog while the system asks for the administrator's password (writing an SD card needs it).
    static var deskFoldersSetupWaitingPermission: String { L("desk.folders.setup_waiting_permission", table: "DeskFolders") }

    /// If Windows offers to format the card, choose Cancel: Windows can't read the device's Linux partition, and that is expected.
    ///
    /// otc-sync (Windows): last paragraph of Set Up a New Device's last dialog. Windows may offer to format the written card, which would erase it: "Cancel" is the button of Windows's own message, in the language Windows shows it in.
    static var deskFoldersSetupWindowsFormat: String { L("desk.folders.setup_windows_format", table: "DeskFolders") }

    /// Try Again
    ///
    /// Both apps, new-device wizard: button that repeats a step that failed - the image download (Mac), or looking for an SD card after none was found (otc-sync). Title Case, as the computer apps' other buttons.
    static var deskFoldersTryAgain: String { L("desk.folders.try_again", table: "DeskFolders") }

    /// You can turn it off later from the web app or the phone app (the lock on the folder in Files); the files you deleted on this computer while it was on then come back here.
    ///
    /// otc-sync: when adding a folder, the sentence after what the option Upload only means: how it is turned off later, and what that brings back. "Files" is the Files section of the web and phone apps.
    static var deskFoldersUploadOnlyLater: String { L("desk.folders.upload_only_later", table: "DeskFolders") }

    /// Files you delete on this computer stay on the device and aren't downloaded again; files added or changed on the device still come down.
    ///
    /// otc-sync: when adding a folder, a sentence of what the option Upload only means for a folder synced both ways, after "The device keeps every older version of a file, and nothing in the folder can be deleted on the device." The Mac says "this Mac" (macos.upload_only.add_info).
    static var deskFoldersUploadOnlyTwoWay: String { L("desk.folders.upload_only_two_way", table: "DeskFolders") }

    /// Yes
    ///
    /// otc-sync (Windows): button that answers yes to a question when adding a folder (keep it out of Images, make it upload only).
    static var deskFoldersYes: String { L("desk.folders.yes", table: "DeskFolders") }
